def run_entity(args):
 prefix=fixture.HARNESS[:fixture.HARNESS.index('int main(')]
 prefix=re.sub(r'namespace GameFileReader \{\nTextReadResult[\s\S]*?\n\}\n\}', '',prefix,count=1)
 with tempfile.TemporaryDirectory(prefix='api500-boundary-')as d:
  binary=build_lua_harness(source_root=fixture.SOURCE,workdir=Path(d),harness_source=prefix+ENTITY_MAIN)
  return subprocess.run([str(binary),*args],capture_output=True,text=True)
class BoundaryConsumers(unittest.TestCase):
 def test_entity_retirement(self):
  r=run_entity(('dead',));self.assertEqual(r.returncode,0,r.stdout+r.stderr)
 def test_entity_success_cache_then_cross_base(self):
  r=run_entity(('crossbase',));self.assertEqual(r.returncode,0,r.stdout+r.stderr)
 def test_world_success_cache_then_cross_base(self):
  r=run_world(main=WORLD_MAIN);self.assertEqual(r.returncode,0,r.stdout+r.stderr)
